const fetch = require('node-fetch');

const FIRECRAWL_API_KEY = $vars.firecrawl_api;
const BASE = 'https://api.firecrawl.dev/v1/scrape';

// ─── Firecrawl helper ─────────────────────────────────────────────
async function scrape(url, options = {}) {
  const res = await fetch(BASE, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${FIRECRAWL_API_KEY}`
    },
    body: JSON.stringify({
      url,
      formats: ['markdown'],
      onlyMainContent: true,
      ...options
    })
  });
  const data = await res.json();
  return data.success
    ? { ok: true, content: data.data.markdown, url }
    : { ok: false, content: `Fetch failed: ${data.error}`, url };
}

// ─── Apple fees: extract iPhone section only ──────────────────────
function extractIphoneFees(markdown) {
  const lines = markdown.split('\n');
  const result = [];
  let capture = false;

  for (const line of lines) {
    if (!capture && line.includes('**iPhone:**')) {
      capture = true;
    }
    if (capture) {
      result.push(line);
      if (result.length > 2 && (
        line.includes('**iPad:**') ||
        line.includes('**AirPods') ||
        line.includes('**Apple TV') ||
        line.includes('**Apple Vision') ||
        line.includes('**Mac:**')
      )) {
        result.pop();
        break;
      }
    }
  }

  return result.length > 0
    ? `**iPhone Service Fees:**\n` + result.join('\n').trim()
    : markdown;
}

// ─── Apple PDF: extract iPhone section only ───────────────────────
function extractIphoneSection(markdown) {
  const lines = markdown.split('\n');

  function extractBlock(startTriggers, stopTriggers) {
    let capture = false;
    const block = [];
    for (const line of lines) {
      if (!capture) {
        if (startTriggers.some(t => line.includes(t))) {
          capture = true;
        }
      }
      if (capture) {
        block.push(line);
        if (block.length > 3 && stopTriggers.some(t => line.includes(t))) {
          block.pop();
          break;
        }
        if (block.length > 80) break;
      }
    }
    return block.join('\n').trim();
  }

  // Updated start triggers to match actual PDF content structure
  const tlTable = extractBlock(
    ['Covered iPhone Model', 'iPhone SE:', '| iPhone SE', 'iPhone SE |'],
    ['iPad:', 'Covered iPad Model', 'Apple Watch:', '13. Country', '## 13.']
  );

  if (!tlTable) {
    return '> Could not extract iPhone pricing table. Visit apple.com/legal/sales-support/applecare/applecareplus/us/ for latest pricing.';
  }

  const baseNote = `> **AppleCare+ Standard (without Theft & Loss)** costs $3.50/mo less on monthly plans and $35/yr less on annual plans than the prices shown above. The 24-month fixed-term plan without T&L is also available at a lower price. Source: Section 12(p) of the AppleCare+ terms.`;

  return `### Plan 1: AppleCare+ with Theft & Loss
Includes: Unlimited accidental damage repairs, theft/loss replacement (up to 2 claims per 12 months), battery service if below 80% capacity, 24/7 priority support.

${tlTable}

---

### Plan 2: AppleCare+ Standard (no Theft & Loss)
Same coverage as Plan 1 except no theft or loss replacement.

${baseNote}

---

### Plan 3: AppleCare One (Multi-Device)
$19.99/mo for up to 3 Apple devices. $5.99/mo per additional device.
Includes Theft & Loss for iPhone, iPad, Apple Watch. Up to 3 T&L claims per year.
Source: apple.com/applecare/`;
}

// ─── Samsung tier map (structural only — no prices) ───────────────
const SAMSUNG_TIER_MAP = {
  // Tier 1 — A series
  'a14':1,'a15':1,'a16':1,'a17':1,
  'a25':1,'a26':1,
  'a35':1,'a36':1,
  'a54':1,'a55':1,'a56':1,

  // Tier 2 — S standard, S+, S FE, S Edge
  's23':2,'s23+':2,'s23 plus':2,'s23 fe':2,
  's24':2,'s24+':2,'s24 plus':2,'s24 fe':2,
  's25':2,'s25+':2,'s25 plus':2,'s25 fe':2,'s25 edge':2,
  's26':2,'s26+':2,'s26 plus':2,'s26 fe':2,'s26 edge':2,

  // Tier 3 — S Ultra + Z Flip
  's23 ultra':3,'s24 ultra':3,'s25 ultra':3,'s26 ultra':3,
  'z flip5':3,'z flip 5':3,
  'z flip6':3,'z flip 6':3,
  'z flip7':3,'z flip 7':3,
  'z flip7 fe':3,'z flip 7 fe':3,

  // Tier 4 — Z Fold (highest)
  'z fold5':4,'z fold 5':4,
  'z fold6':4,'z fold 6':4,
  'z fold7':4,'z fold 7':4,
};

function resolveSamsungTier(model) {
  const m = model.toLowerCase().replace('galaxy', '').trim();
  const sorted = Object.entries(SAMSUNG_TIER_MAP).sort((a, b) => b[0].length - a[0].length);
  for (const [key, tier] of sorted) {
    if (m.includes(key)) return tier;
  }
  return null;
}

