- Other accidental damage (ADH): ${t.adh_fee}
- Theft or loss replacement: ${t.tl_fee}

> Pricing as of Jan 2025. Source: samsung.com/us/support/samsung-care-plus/
> Note: Samsung's pricing table is rendered as SVG on their website and cannot be fetched programmatically. These figures are sourced from Samsung's official tier schedule document.`;
}

// ─── Brand config ─────────────────────────────────────────────────
const BRAND_CONFIG = {

  apple: {
    sources: [
      {
        label: 'APPLECARE+ SERVICE FEES & DEDUCTIBLES',
        url: 'https://www.apple.com/legal/applecare/fees-deductibles/',
        mode: 'static'
      },
      {
        label: 'APPLECARE+ PLAN PRICING & TERMS (iPHONE)',
        url: 'https://www.apple.com/legal/sales-support/applecare/applecareplus/2603/260302_applecareplus_us.pdf',
        mode: 'pdf'   // back to pdf — extractIphoneSection() runs in this branch
      }
    ],
    note: 'Apple limited warranty (1 year, manufacturing defects) is referenced within the AppleCare+ terms above under Sections 3 and 4.'
  },

  samsung: {
    sources: [
      {
        label: 'LIMITED WARRANTY',
        url: 'https://www.samsung.com/us/support/warranty/',
        mode: 'static'
      },
      {
        label: 'SAMSUNG CARE+ PLAN FEATURES',
        url: 'https://www.samsung.com/us/support/samsung-care-plus/',
        mode: 'js'
      }
    ]
  },

  google: {
    sources: [
      {
        label: 'LIMITED WARRANTY',
        url: 'https://support.google.com/product-documentation/answer/9322027',
        mode: 'static'
      },
      {
        label: 'PIXEL CARE+ PLAN FEATURES & PRICING',
        url: 'https://support.google.com/store/answer/16496166',
        mode: 'static'
      }
    ]
  },

  motorola: {
    sources: [
      {
        label: 'LIMITED WARRANTY',
        url: 'https://help.motorola.com/hc/apps/settings/legal/global/en-us/CGT1507061106.html',
        mode: 'static'
      },
      {
        label: 'MOTO CARE EXTENDED PLAN — FEATURES & PRICING',
        url: 'https://www.motorola.com/us/en/moto-care/',
        mode: 'js'
      }
    ]
  },

  nothing: {
    sources: [
      {
        label: 'LIMITED WARRANTY',
        url: 'https://support.nothing.tech/hc/en-us/sections/38494777022353-Warranty',
        mode: 'static'
      }
    ],
    note: 'Nothing does not offer an official extended warranty or protection plan in the US market. Third-party options such as Upsie may be available.'
  }
};

// ─── Main execution ───────────────────────────────────────────────
try {
  const brand = ($brand || '').toLowerCase().trim();
  const model = ($model || '').trim();

  const config = BRAND_CONFIG[brand];
  if (!config) {
    return `Brand "${brand}" is not supported. Supported brands: Apple, Samsung, Google, Motorola, Nothing.`;
  }

  const APPLE_PDF_FALLBACK = 'https://www.apple.com/legal/sales-support/applecare/applecareplus/2603/260302_applecareplus_us.pdf';
  const APPLE_PDF_INDEX    = 'https://www.apple.com/legal/sales-support/applecare/applecareplus/us/';

  const fetchPromises = config.sources.map(async (source) => {
    let result;

    if (source.mode === 'pdf') {
      // No parsers key — Firecrawl auto-detects PDF from URL
      const directRes = await fetch(BASE, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${FIRECRAWL_API_KEY}`
        },
        body: JSON.stringify({
          url: source.url,
          formats: ['markdown']
        })
      });
      const directData = await directRes.json();

      if (directData.success) {
        const filtered = extractIphoneSection(directData.data.markdown);
        result = { ok: true, content: filtered, url: source.url };
      } else {
        // Fallback: find latest PDF from index page
        try {
          const indexRes = await fetch(BASE, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${FIRECRAWL_API_KEY}`
            },
            body: JSON.stringify({
              url: APPLE_PDF_INDEX,
              formats: ['markdown', 'links'],
              onlyMainContent: true
            })
          });
          const indexData = await indexRes.json();
          const latestUrl = indexData.success
            ? (indexData.data.links || []).find(l =>
                l.includes('applecareplus_us.pdf') &&
                !l.includes('tl_disclosures') &&
                !l.includes('_ny.pdf')
              )
            : null;

          const pdfToFetch = latestUrl || APPLE_PDF_FALLBACK;

          const fallbackRes = await fetch(BASE, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${FIRECRAWL_API_KEY}`
            },
            body: JSON.stringify({
              url: pdfToFetch,
              formats: ['markdown']
            })
          });
          const fallbackData = await fallbackRes.json();

          if (fallbackData.success) {
            const filtered = extractIphoneSection(fallbackData.data.markdown);
            result = { ok: true, content: filtered, url: pdfToFetch };
          } else {
            result = {
              ok: false,
              content: `PDF fetch failed: ${fallbackData.error}. Visit ${APPLE_PDF_INDEX} for latest pricing.`,
              url: pdfToFetch
            };
          }
        } catch (e) {
          result = {
            ok: false,
            content: `PDF fetch error: ${e.message}. Visit ${APPLE_PDF_INDEX} for latest pricing.`,
            url: source.url
          };
        }
      }

    } else if (source.mode === 'js') {
      result = await scrape(source.url, { waitFor: 2000 });

    } else {
      result = await scrape(source.url);
      if (result.ok && source.url.includes('fees-deductibles')) {
        result.content = extractIphoneFees(result.content);
      }
    }

    return { label: source.label, ...result };
  });

  const results = await Promise.all(fetchPromises);

  const header = model
    ? `WARRANTY INFORMATION — ${brand.toUpperCase()} ${model.toUpperCase()}`
    : `WARRANTY INFORMATION — ${brand.toUpperCase()}`;

  const sections = results.map((r, i) => {
    const status = r.ok ? '' : ' ⚠️ FETCH ERROR';
    return `### ${i + 1}. ${r.label}${status}\nSource: ${r.url}\n\n${r.content}`;
  }).join('\n\n---\n\n');

  let samsungPricing = '';
  if (brand === 'samsung') {
    const tier = model ? resolveSamsungTier(model) : null;
    if (tier) {
      const pricingText = getSamsungTierPricing(tier, model);
      samsungPricing = `\n\n---\n\n### ${results.length + 1}. SAMSUNG CARE+ PRICING — ${model.toUpperCase()}\n\n${pricingText}`;
    } else if (model) {
      samsungPricing = `\n\n---\n\n### ${results.length + 1}. SAMSUNG CARE+ PRICING\n\n> Model "${model}" not found in tier map. Visit samsung.com/us/support/samsung-care-plus/ to check pricing for your specific device.`;
    }
  }

  const note = config.note
    ? `\n\n---\n\n> ℹ️ ${config.note}`
    : '';

  return `## ${header}\n\n${sections}${samsungPricing}${note}`;

} catch (err) {
  return `Tool error: ${err.message}`;
}
